/* C API of the Rust port of `avstring.c`, generated by rust-anything. */
#ifndef AVSTRING_RS_H
#define AVSTRING_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

char *av_stristr(const char *s1, const char *s2);
char *av_strnstr(const char *haystack, const char *needle, size_t hay_length);
size_t av_strlcpy(char *dst, const char *src, size_t size);
size_t av_strlcat(char *dst, const char *src, size_t size);
int av_strcasecmp(const char *a, const char *b);
int av_strncasecmp(const char *a, const char *b, size_t n);
int av_match_name(const char *name, const char *names);
int av_match_list(const char *name, const char *list, char separator);

/* The same functions under `rust_anything_` names, for shadow runs. */
char *rust_anything_av_stristr(const char *s1, const char *s2);
char *rust_anything_av_strnstr(const char *haystack, const char *needle, size_t hay_length);
size_t rust_anything_av_strlcpy(char *dst, const char *src, size_t size);
size_t rust_anything_av_strlcat(char *dst, const char *src, size_t size);
int rust_anything_av_strcasecmp(const char *a, const char *b);
int rust_anything_av_strncasecmp(const char *a, const char *b, size_t n);
int rust_anything_av_match_name(const char *name, const char *names);
int rust_anything_av_match_list(const char *name, const char *list, char separator);

#endif /* AVSTRING_RS_H */
